import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nextLong();
        // stop[i]: first j > i with prefix[j] < prefix[i] (monotonic stack).
        int[] stop = new int[n + 1], stack = new int[n + 1];
        Arrays.fill(stop, n + 1);
        int top = 0;
        for (int i = 0; i <= n; i++) {
            while (top > 0 && prefix[stack[top - 1]] > prefix[i]) stop[stack[--top]] = i;
            stack[top++] = i;
        }
        int answer = 0;
        for (int i = 0; i < n; i++) answer = Math.max(answer, stop[i] - i - 1);
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	prefix := make([]int, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i] + nextInt()
	}
	// stop[i]: first j > i with prefix[j] < prefix[i] (monotonic stack).
	stop := make([]int, n+1)
	for i := range stop {
		stop[i] = n + 1
	}
	stack := make([]int, 0, n+1)
	for i := 0; i <= n; i++ {
		for len(stack) > 0 && prefix[stack[len(stack)-1]] > prefix[i] {
			stop[stack[len(stack)-1]] = i
			stack = stack[:len(stack)-1]
		}
		stack = append(stack, i)
	}
	answer := 0
	for i := 0; i < n; i++ {
		answer = max(answer, stop[i]-i-1)
	}
	fmt.Println(answer)
}
